You are a MECHANICAL WRITER. Create the file .agile-js/report-schema.json (create its directory if needed) whose ENTIRE content is exactly the JSON below - verbatim, no edits, no extra keys, no commentary.
Then report written=true (written=false only when the write really failed).

Every long command runs with piped stdin and an explicit timeout; running servers, tests or solvers without piped stdin is a violation. Work incrementally.

FINAL MESSAGE DISCIPLINE: your final message must be ONLY the JSON value with EXACTLY the schema keys listed in your instructions. Do NOT emit acceptanceReport or any other key; narrative goes inside string fields.

Schema keys: written.
JSON CONTENT:
{
  "work": {
    "type": "object",
    "properties": {
      "what_done": {
        "type": "string"
      },
      "files_changed": {
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "verification": {
        "type": "string"
      },
      "branch": {
        "type": "string"
      },
      "worktree": {
        "type": "string"
      },
      "completed": {
        "type": "boolean"
      },
      "head": {
        "type": "string",
        "pattern": "^[0-9a-f]{40}$",
        "description": "Full 40-hex SHA of your branch HEAD after the final commit (git rev-parse HEAD)"
      },
      "plan_progress": {
        "type": "string",
        "description": "Ceremony plan completion, e.g. '4/5 done, 1 n/a'"
      },
      "testsAddedOrUpdated": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Test files with case counts ('<file>: <N> cases'); [] exactly when the task adds no tests"
      },
      "commandsRun": {
        "type": "array",
        "minItems": 1,
        "items": {
          "type": "object",
          "properties": {
            "command": {
              "type": "string"
            },
            "result": {
              "type": "string",
              "enum": [
                "passed",
                "failed",
                "not-run"
              ]
            },
            "summary": {
              "type": "string"
            }
          },
          "required": [
            "command",
            "result",
            "summary"
