        "items": {
          "type": "string"
        }
      },
      "residualRisks": {
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "noStagedFiles": {
        "type": "boolean",
        "description": "true only when `git status --short` is empty in your tree after the final commit"
      },
      "criteriaSatisfied": {
        "type": "array",
        "minItems": 2,
        "maxItems": 2,
        "items": {
          "type": "object",
          "properties": {
            "id": {
              "type": "string",
              "enum": [
                "criterion-1",
                "criterion-2"
              ]
            },
            "status": {
              "type": "string",
              "enum": [
                "satisfied"
              ]
            },
            "evidence": {
              "type": "string"
            }
          },
          "required": [
            "id",
            "status",
            "evidence"
          ],
          "additionalProperties": false
        }
      }
    },
    "required": [
      "what_done",
      "files_changed",
      "verification",
      "branch",
      "worktree",
      "completed",
      "head",
      "testsAddedOrUpdated",
      "commandsRun",
      "validationOutput",
      "residualRisks",
      "noStagedFiles",
      "criteriaSatisfied"
    ],
    "additionalProperties": false
  },
  "merge": {
    "type": "object",
    "properties": {
      "merged": {
        "type": "boolean"
      },
      "checks_ok": {
        "type": "boolean"
      },
      "journal_written": {
        "type": "boolean"
      },
      "merge_commit": {
        "type": "string"
      },
      "bd_closed": {
        "type": "boolean"
      },
      "branch_deleted": {
        "type": "boolean"
